import React, { useContext } from "react";
import { AuthContext } from "../Context/AuthContext";

function Toolbar({ socket }) {
  const { user } = useContext(AuthContext);

  const getRoleGradient = (role) => {
    switch (role) {
      case "admin": return "from-purple-500 via-pink-500 to-red-500";
      case "editor": return "from-blue-500 via-cyan-500 to-teal-500";
      case "viewer": return "from-gray-500 via-slate-500 to-zinc-500";
      default: return "from-gray-400 to-gray-500";
    }
  };

  const getRoleIcon = (role) => {
    switch (role) {
      case "admin": return "👑";
      case "editor": return "✏️";
      case "viewer": return "👁️";
      default: return "👤";
    }
  };

  return (
    <div className="flex p-6 bg-gradient-to-r from-gray-100 via-blue-100 to-indigo-100 border-b border-blue-200 shadow-sm relative overflow-hidden">
      {/* Decorative Background Elements */}
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-0 left-0 w-20 h-20 bg-blue-300 rounded-full blur-xl"></div>
        <div className="absolute bottom-0 right-0 w-24 h-24 bg-purple-300 rounded-full blur-xl"></div>
      </div>
      
      <div className="flex items-center justify-between w-full max-w-6xl mx-auto relative z-10">
        <div className="flex items-center space-x-6">
          {/* Connection Status */}
          <div className="flex items-center space-x-3 bg-white/80 backdrop-blur-lg rounded-2xl px-5 py-3 shadow-xl border border-white/50 hover:shadow-2xl transition-all duration-300">
            <div className="relative">
              <div className="w-4 h-4 bg-green-400 rounded-full animate-pulse shadow-lg"></div>
              <div className="absolute inset-0 w-4 h-4 bg-green-400 rounded-full animate-ping opacity-75"></div>
            </div>
            <span className="text-sm font-semibold text-gray-700">
              Real-time collaboration active
            </span>
          </div>
          
          {/* User Info */}
          <div className="bg-white/80 backdrop-blur-lg rounded-2xl px-5 py-3 shadow-xl border border-white/50 hover:shadow-2xl transition-all duration-300">
            <div className="flex items-center space-x-3">
              <div className="w-8 h-8 bg-gradient-to-br from-blue-400 to-purple-500 rounded-full flex items-center justify-center shadow-lg">
                <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
              </div>
              <div>
                <span className="text-sm text-gray-600 font-medium">Connected as:</span>
                <span className="ml-2 text-sm font-semibold text-gray-800">{user?.username}</span>
              </div>
            </div>
          </div>
        </div>
        
        {/* Role Badge */}
        <div className="flex items-center space-x-4">
          <div className={`bg-gradient-to-r ${getRoleGradient(user?.role)} text-white px-6 py-3 rounded-2xl shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:scale-105`}>
            <div className="flex items-center space-x-3">
              <span className="text-2xl">{getRoleIcon(user?.role)}</span>
              <div>
                <span className="text-sm font-bold block">
                  {user?.role === "admin" && "Admin Mode"}
                  {user?.role === "editor" && "Editor Mode"}
                  {user?.role === "viewer" && "Viewer Mode"}
                </span>
                <span className="text-xs opacity-90">
                  {user?.role === "admin" && "Full control + clear board"}
                  {user?.role === "editor" && "Can draw and erase"}
                  {user?.role === "viewer" && "Read-only access"}
                </span>
              </div>
            </div>
          </div>
          
          {/* Additional Status Indicators */}
          <div className="bg-white/60 backdrop-blur-lg rounded-2xl px-4 py-3 shadow-lg border border-white/50">
            <div className="flex items-center space-x-2">
              <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></div>
              <span className="text-xs text-gray-600 font-medium">Socket Connected</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Toolbar;
